def kind(kw):
    k = KIND_SPEC.sub("", KIND_MOD.sub("", KIND_MODEL.sub("", re.sub(r"\s+", "", kw.lower()))))
    for rx, rep in KIND_SYN:
        k = rx.sub(rep, k)
    return k or kw






